function validate([s, pattern]) {
  if (pattern.length < 1) return 'pattern needs at least one letter.';
  if (pattern.length >= s.length) return 'pattern must be shorter than s.';
  if (s.length > 100000) return 's has at most 100000 letters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(pattern)) return 's and pattern use only lowercase English letters.';
  return null;
}

