function minStartingIndex(s, pattern) {
  const zFunction = (text) => {
    const z = new Array(text.length).fill(0);
    let left = 0;
    let right = 0;
    for (let i = 1; i < text.length; i++) {
      if (i < right) {
        z[i] = Math.min(right - i, z[i - left]);
      }
      while (i + z[i] < text.length && text[z[i]] === text[i + z[i]]) {
        z[i]++;
      }
      if (i + z[i] > right) {
        left = i;
        right = i + z[i];
      }
    }
    return z;
  };
  const reverse = (text) => text.split('').reverse().join('');
  const n = s.length;
  const m = pattern.length;
  const prefix = zFunction(pattern + '#' + s);
  const suffix = zFunction(reverse(pattern) + '#' + reverse(s));
  for (let i = 0; i + m <= n; i++) {
    const front = prefix[m + 1 + i];
    const back = suffix[n + 1 - i];
    if (front + back >= m - 1) {
      return i;
    }
  }
  return -1;
}

