function minStartingIndex(s, pattern) {
  // Compare every window letter by letter, giving up on it at the second difference.
  for (let start = 0; start + pattern.length <= s.length; start++) {
    let differences = 0;
    for (let j = 0; j < pattern.length && differences < 2; j++) {
      if (s[start + j] !== pattern[j]) differences++;
    }
    if (differences <= 1) return start;
  }
  return -1;
}

