function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'large') {
    const n = 10000;
    const m = 1000 + Math.floor(rand() * 4000);
    if (rand() < 0.4) {
      // Long runs of one letter: a window-by-window comparison reads almost all of pattern at every start.
      return ['a'.repeat(n - 1) + 'b', 'a'.repeat(m - 2) + 'bb'];
    }
    const text = Array.from({ length: n }, () => letters[Math.floor(rand() * 2)]);
    const start = Math.floor(rand() * (n - m + 1));
    const copy = text.slice(start, start + m);
    const changes = 1 + Math.floor(rand() * 2);
    for (let c = 0; c < changes; c++) {
      const at = Math.floor(rand() * m);
      copy[at] = copy[at] === 'a' ? 'b' : 'a';
    }
    return [text.join(''), copy.join('')];
  }
  const n = 2 + Math.floor(rand() * 11);
  // Longer patterns are favoured: with one or two letters almost every window qualifies.
  const m = 1 + Math.floor(Math.sqrt(rand()) * (n - 1));
  const alphabet = 2 + Math.floor(rand() * 4);
  const pick = () => letters[Math.floor(rand() * alphabet)];
  const text = Array.from({ length: n }, pick);
  let copy = Array.from({ length: m }, pick);
  if (rand() < 0.6) {
    // Copy a window of s and change one or two letters, so near hits and near misses are common.
    const start = Math.floor(rand() * (n - m + 1));
    copy = text.slice(start, start + m);
    const changes = 1 + Math.floor(rand() * 2);
    for (let c = 0; c < changes; c++) copy[Math.floor(rand() * m)] = pick();
  }
  return [text.join(''), copy.join('')];
}
